def table_given_header(self, header, fields=None):
    no_fields_filter = False
    if fields is None:
        no_fields_filter = True
        fields = []
    fields = set(fields)
    docs = list(self.docs_given_header(header=header,
                                fill=False, fields=fields))
    # Convert timestamps to the specified timezone
    for doc in docs:
        if 'time' in doc:
            doc['time'] = _munge_time(doc['time'], self.tz)
    return pd.DataFrame.from_records(data=docs, index='seq_num')

def makeService(self, options):
    serverType = config.ProcessType

    serviceMethod = getattr(self, "makeService_%s" % (serverType,), None)

    if not serviceMethod:
        raise UsageError(
            "Unknown server type %s. "
            "Please choose: Master, Slave or Combined"
            % (serverType,)
        )
    else:
        service = serviceMethod(options)

        def location(frame):
            if frame is None:
                return "Unknown"
            else:
                return "%s: %s" % (frame.f_code.co_name, frame.f_lineno)

        import signal
        def sigusr1_handler(num, frame):
            log.msg("SIGUSR1 recieved at %s" % (location(frame),))
            logging.toggle()
        signal.signal(signal.SIGUSR1, sigusr1_handler)

        return service

