def check_config_option_in_central_place(logical_line, filename):
    msg = ("N342: Config options should be in the central location 
           '/nova/conf/*'. Do not declare new config options outside 
           of that folder.")
    # That's the correct location
    if "nova/conf/" in filename:
        return
    cleaned_up = ["nova/console/serial.py",
                  "nova/cmd/serialproxy.py",
                  ]
    if not any(c in filename for c in cleaned_up):
        return

    if cfg_opt_re.match(logical_line):
        yield(0, msg)

def getAtomCategory(atom):
    try:
        rc = portage.portdb.xmatch("match-all", str(atom))[0].split("/")[0]
        return rc
    except:
        return None

def get_xray_structures(processed_pdb_file, scattering_table, d_min):
  xray_structure = processed_pdb_file.xray_structure()
  if(xray_structure is None or xray_structure.scatterers().size()==0):
    raise Sorry("Cannot extract xray_structure.")
  if(scattering_table != "neutron"):
    xray_structure.scattering_type_registry(
      table = scattering_table,
      d_min = d_min,
      types_without_a_scattering_contribution=["?"])
  else:
    xray_structure.scattering_type_registry(
      types_without_a_scattering_contribution=["?"])
    xray_structure.switch_to_neutron_scattering_dictionary()
  model_indices = processed_pdb_file.all_chain_proxies.pdb_inp.model_indices()
  if(len(model_indices)>1):
     result = []
     model_indices_padded = flex.size_t([0])
     model_indices_padded.extend(model_indices)
     ranges = []
     for i, v in enumerate(model_indices_padded):
       try: ranges.append([model_indices_padded[i], model_indices_padded[i+1]])
       except IndexError: pass
     for ran in ranges:
       sel = flex.size_t(range(ran[0],ran[1]))
       result.append(xray_structure.select(sel))
     return result
  else:
    return [xray_structure]

def _get_fragment(self, chunk_iter, storage_method):
    headers = {'Content-Type': 'application/octet-stream'}  # Generate proper headers
    reader = io.ChunkReader(chunk_iter, storage_method.ec_fragment_size,
                            headers, self.connection_timeout,
                            self.response_timeout, self.read_timeout)
    return (reader, reader.get_iter())

