def run(self):
    latest_state = None
    with kombu.Connection(self._amqp_url) as conn:
        q = conn.SimpleQueue("brozzler.sites.unclaimed")
        while not self._shutdown_requested.is_set():
            try:
                q_empty = False
                if len(q) > 0:
                    try:
                        self._claim_site(q)
                    except kombu.simple.Empty:
                        q_empty = True
                    except KeyError:
                        if latest_state != "browsers-busy":
                            self.logger.info("all {} browsers are busy".format(self._max_browsers))
                            latest_state = "browsers-busy"
                else:
                    q_empty = True

                if q_empty:
                    if latest_state != "no-unclaimed-sites":
                        latest_state = "no-unclaimed-sites"
                time.sleep(0.5)
            except OSError as e:
                self.logger.warn("continuing after i/o exception (from rabbitmq?)", exc_info=True)

def _request_params(self):
    params = super(FileRequest, self)._request_params

    data = self.files or {}
    data["json"] = ("json", json.dumps(self.data), "application/json")

    callback = self.progress_callback or (lambda x: x)
    m = MultipartEncoder(data)
    params["json"] = None
    params["data"] = MultipartEncoderMonitor(m, callback)
    params["headers"] = {'Content-Type': params["data"].content_type}
    return params

