def get_first_applied_membership_fee() -> MembershipFee:
    """Get the first applied membership fee."""
    return typing.cast(
        MembershipFee,
        MembershipFee.select().order_by(MembershipFee.ends_on.desc()).first()
    )

async def calc_metrics_developer(request: AthenianWebRequest, body: dict) -> web.Response:
    """Calculate metrics over developer activities."""
    try:
        filt = DeveloperMetricsRequest.from_dict(body)
    except ValueError as e:
        # for example, passing a date with day=32
        return ResponseError(InvalidRequestError("?", detail=str(e))).response
    filters, release_settings = await _compile_repos_and_devs_devs(filt.for_, request, filt.account)
    if filt.date_to < filt.date_from:
        return ResponseError(InvalidRequestError(
            detail="date_from may not be greater than date_to",
            pointer=".date_from",
        )).response

    met = CalculatedDeveloperMetrics()
    met.date_from = filt.date_from
    met.date_to = filt.date_to
    met.timezone = filt.timezone
    met.metrics = filt.metrics
    met.calculated = []
    topics = {DeveloperTopic(t) for t in filt.metrics}
    time_from, time_to = filt.resolve_time_from_and_to()
    tasks = []
    for_sets = []
    for service, (repos, devs, labels, jira, for_set) in filters:
        tasks.append(METRIC_ENTRIES[service]["developers"](
            devs, repos, topics, labels, jira, time_from, time_to, request.mdb, request.cache))
        for_sets.append(for_set)
    all_stats = await asyncio.gather(*tasks, return_exceptions=True)
    for stats, for_set in zip(all_stats, for_sets):
        if isinstance(stats, Exception):
            raise stats from None
        met.calculated.append(CalculatedDeveloperMetricsItem(
            for_=for_set,
            values=[[getattr(s, DeveloperTopic(t).name) for t in filt.metrics] for s in stats],
        ))
    return model_response(met)

def _validator_items(self, field, value):
    if isinstance(value, Mapping):
        self._validator_schema(field, value)
    else:
        for i, schema in enumerate(value):
            self._validator_bulk_schema((field, i), schema)

def s3(self):
    required_fields = {
        'static-bucket-name': 'BucketName'
    }

    present_keys = self.data['s3'].keys()
    for i in required_fields.keys():
        if i not in present_keys:
            print "\n\n[ERROR] Missing S3 fields [%s]" % i
            sys.exit(1)

    bucket = Bucket(
        "StaticBucket",
        AccessControl="BucketOwnerFullControl",
        BucketName=self.data['s3']['static-bucket-name'],
    )

    if 'policy' in present_keys:
        policy = json.loads(open(self.data['s3']['policy']).read())
    else:
        arn = 'arn:aws:s3:::%s/*' % self.data['s3']['static-bucket-name']
        policy = {
            'Action': ['s3:GetObject'],
            'Resource': arn,
            'Effect': 'Allow',
            'Principal': '*'}

    bucket_policy = BucketPolicy(
        "StaticBucketPolicy",
        Bucket=Ref(bucket),
        PolicyDocument={"Statement": [policy]},
    )

    resources = [bucket, bucket_policy]
    return resources

